def purchaser_as_holder(apps, schema_editor):
    # Tickets issued before holder details existed are held by their purchaser,
    # exactly as checkout now does when no attendee is given.
    Ticket = apps.get_model("ticketing", "Ticket")
    tickets = list(Ticket.objects.select_related("order_item__order__purchaser"))
    for ticket in tickets:
        purchaser = ticket.order_item.order.purchaser
        full_name = f"{purchaser.first_name} {purchaser.last_name}".strip()
        ticket.attendee_name = full_name or purchaser.email
        ticket.attendee_email = purchaser.email
    Ticket.objects.bulk_update(tickets, ["attendee_name", "attendee_email"], batch_size=500)


